<script setup>
import { onMounted, reactive, ref } from 'vue'
import api from '../services/api'
import { findLocationByPostalCode, getStates, isMexicanPostalCode, searchNeighborhoods } from '../services/locationDirectory.js'
const emit = defineEmits(['registered'])
const emptyForm = () => ({ firstName: '', paternalSurname: '', maternalSurname: '', curp: '', rfc: '', birthDate: '', age: '', contactEmail: '', contactMobile: '', personalMobile: '', workPhone: '', street: '', locality: '', municipality: '', state: '', postalCode: '', workshopId: '' })
const form = reactive(emptyForm())
const photo = ref(null), workshops = ref([]), neighborhoodOptions = ref([]), stateCode = ref(''), localityId = ref('')
const loading = ref(false), locationLoading = ref(false), error = ref(''), success = ref(''), locationFeedback = ref('')
const states = getStates()
const CURP = /^[A-Z]{4}[0-9]{6}[HM][A-Z]{5}[A-Z0-9][0-9]$/
const RFC = /^[A-Z&Ñ]{3,4}[0-9]{2}(0[1-9]|1[0-2])(0[1-9]|[12][0-9]|3[01])[A-Z0-9]{3}$/
async function loadWorkshops() { try { workshops.value = (await api.get('/workshops')).data } catch { error.value = 'No fue posible cargar los talleres disponibles.' } }
function title(value) { return value.trim().toLowerCase().replace(/\b\p{L}/gu, (letter) => letter.toUpperCase()) }
function onPhoto(event) { photo.value = event.target.files?.[0] || null; if (photo.value?.size > 7 * 1024 * 1024) { photo.value = null; event.target.value = ''; error.value = 'La fotografia no puede superar 7 MB.' } }
function applyLocation(location) { form.state = location.state; stateCode.value = location.stateCode; form.municipality = location.municipality; form.locality = location.neighborhood; form.postalCode = location.postalCode; localityId.value = location.id }
async function onPostalCode() { form.postalCode = form.postalCode.replace(/\D/g, '').slice(0, 5); localityId.value = ''; neighborhoodOptions.value = []; if (!isMexicanPostalCode(form.postalCode)) return; locationLoading.value = true; try { const result = await findLocationByPostalCode(form.postalCode); if (!result) { locationFeedback.value = 'El codigo postal no fue encontrado.'; return } stateCode.value = result.stateCode; form.state = result.state; form.municipality = result.municipality; neighborhoodOptions.value = result.neighborhoods; locationFeedback.value = `Selecciona la localidad de ${result.municipality}.`; if (result.neighborhoods.length === 1) applyLocation(result.neighborhoods[0]) } finally { locationLoading.value = false } }
async function searchLocality(event) { const query = event.target.value.trim(); if (!stateCode.value || query.length < 3) return; locationLoading.value = true; try { neighborhoodOptions.value = await searchNeighborhoods(stateCode.value, query) } finally { locationLoading.value = false } }
function selectLocality() { const selected = neighborhoodOptions.value.find((item) => item.id === localityId.value); if (selected) applyLocation(selected) }
function selectState() { const state = states.find((item) => item.code === stateCode.value); form.state = state?.name || ''; form.municipality = ''; form.locality = ''; form.postalCode = ''; neighborhoodOptions.value = [] }
async function registerClient() { error.value = ''; success.value = ''; form.curp = form.curp.trim().toUpperCase(); form.rfc = form.rfc.trim().toUpperCase(); if (!CURP.test(form.curp) || !RFC.test(form.rfc)) { error.value = 'Verifica el formato de CURP y RFC.'; return } if (!photo.value || !form.workshopId || !localityId.value) { error.value = 'Selecciona taller, fotografia y una localidad valida.'; return } for (const key of ['firstName', 'paternalSurname', 'maternalSurname', 'street', 'locality', 'municipality', 'state']) form[key] = title(form[key]); const payload = new FormData(); Object.entries(form).forEach(([key, value]) => payload.append(key, value)); payload.append('photo', photo.value); loading.value = true; try { const { data } = await api.post('/clients', payload, { headers: { 'Content-Type': 'multipart/form-data' } }); success.value = `${data.message} Folio: ${data.clientId}.`; Object.assign(form, emptyForm()); photo.value = null; localityId.value = ''; neighborhoodOptions.value = []; document.getElementById('client-photo').value = ''; emit('registered') } catch (requestError) { error.value = requestError.response?.data?.message || 'No fue posible registrar el cliente.' } finally { loading.value = false } }
onMounted(loadWorkshops)
</script>
<template>
  <section class="client-registration"><div class="section-heading client-heading"><div><p class="eyebrow">Administracion de clientes</p><h2>Registrar cliente</h2></div><span class="form-note">Todos los campos son obligatorios</span></div>
    <form class="client-form" @submit.prevent="registerClient">
      <div class="form-section"><h3>Identidad y taller</h3><div class="form-grid">
        <label>Taller<select v-model="form.workshopId" class="form-select" required><option value="" disabled>Selecciona un taller</option><option v-for="workshop in workshops" :key="workshop.id" :value="workshop.id">{{ workshop.name }}</option></select></label>
        <label>Nombre<input v-model.trim="form.firstName" class="form-control" required /></label><label>Apellido paterno<input v-model.trim="form.paternalSurname" class="form-control" required /></label><label>Apellido materno<input v-model.trim="form.maternalSurname" class="form-control" required /></label>
        <label>CURP<input v-model="form.curp" class="form-control" maxlength="18" required /></label><label>RFC<input v-model="form.rfc" class="form-control" maxlength="13" required /></label><label>Fecha de nacimiento<input v-model="form.birthDate" class="form-control" type="date" required /></label><label>Edad<input v-model.number="form.age" class="form-control" type="number" min="0" max="130" required /></label><label>Fotografia (maximo 7 MB)<input id="client-photo" class="form-control" type="file" accept="image/*" required @change="onPhoto" /></label>
      </div></div>
      <div class="form-section"><h3>Contacto</h3><div class="form-grid"><label>Correo de contacto<input v-model.trim="form.contactEmail" class="form-control" type="email" required /></label><label>Telefono del contacto<input v-model.trim="form.contactMobile" class="form-control" required /></label><label>Telefono celular personal<input v-model.trim="form.personalMobile" class="form-control" required /></label><label>Telefono de trabajo<input v-model.trim="form.workPhone" class="form-control" required /></label></div></div>
      <div class="form-section"><h3>Direccion</h3><div class="form-grid"><label>Calle<input v-model.trim="form.street" class="form-control" required /></label><label>Codigo postal<input v-model="form.postalCode" class="form-control" inputmode="numeric" maxlength="5" required @input="onPostalCode" /></label><label>Estado<select v-model="stateCode" class="form-select" required @change="selectState"><option value="" disabled>Selecciona un estado</option><option v-for="state in states" :key="state.code" :value="state.code">{{ state.name }}</option></select></label><label>Buscar localidad<input class="form-control" :disabled="!stateCode" @input="searchLocality" /></label><label>Localidad<select v-model="localityId" class="form-select" required @change="selectLocality"><option value="" disabled>Selecciona una localidad</option><option v-for="item in neighborhoodOptions" :key="item.id" :value="item.id">{{ item.neighborhood }}</option></select></label><label>Municipio<input v-model="form.municipality" class="form-control" readonly required /></label></div><p v-if="locationLoading || locationFeedback" class="location-feedback">{{ locationLoading ? 'Consultando catalogo...' : locationFeedback }}</p></div>
      <div v-if="error" class="alert alert-danger mb-0">{{ error }}</div><div v-if="success" class="alert alert-success mb-0">{{ success }}</div><button class="btn btn-danger register-client-button" :disabled="loading">{{ loading ? 'Guardando...' : 'Guardar cliente' }}</button>
    </form></section>
</template>
